#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    // Handle argument count edge cases
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }
    // The original binary limits the total number of arguments (including program name)
    // to 14. That means at most 12 coefficients (argv[2]..argv[13]).
    if (argc > 14) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Parse the evaluation point (x) from argv[1]
    char *endptr;
    long long x = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Range check for x: absolute value must be <= 10
    if (x > 10 || x < -10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Parse coefficients and evaluate using Horner's method
    long long result = 0;
    for (int i = 2; i < argc; ++i) {
        long long coeff = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
        if (coeff > 1000) { // only positive overflow is checked in the original
            puts("OUT_OF_RANGE");
            return 0;
        }
        result = result * x + coeff;
    }

    printf("%lld\n", result);
    return 0;
}
